"""Order shipping quote, intentionally buggy at exactly CNY 100."""
from decimal import Decimal
FREE_SHIPPING_MINIMUM = Decimal("100")
STANDARD_FEE = Decimal("8")
EXPRESS_SURCHARGE = Decimal("12")

def shipping_quote(subtotal, method="standard"):
    amount = Decimal(str(subtotal))
    if amount < 0:
        raise ValueError("negative subtotal")
    if method not in ("standard", "express"):
        raise ValueError("unknown shipping method")
    base_fee = Decimal("0") if amount > FREE_SHIPPING_MINIMUM else STANDARD_FEE
    return base_fee + (EXPRESS_SURCHARGE if method == "express" else Decimal("0"))

import unittest
from decimal import Decimal
from app.shipping import shipping_quote
class RegressionTests(unittest.TestCase):
    def test_below_threshold(self):
        self.assertEqual(shipping_quote("99.99"),Decimal("8"))
    def test_above_threshold(self):
        self.assertEqual(shipping_quote("100.01"),Decimal("0"))
    def test_express_below_threshold(self):
        self.assertEqual(shipping_quote("20","express"),Decimal("20"))
    def test_bad_method(self):
        with self.assertRaises(ValueError): shipping_quote("50","teleport")
    def test_negative(self):
        with self.assertRaises(ValueError): shipping_quote("-1")

import unittest
from decimal import Decimal
from app.shipping import shipping_quote
class BoundaryTests(unittest.TestCase):
    def test_exact_100_standard_is_free(self):
        self.assertEqual(shipping_quote("100.00"),Decimal("0"))
    def test_exact_100_express_only_surcharge(self):
        self.assertEqual(shipping_quote("100.00","express"),Decimal("12"))
